class Component extends DCLogic {
  componentDidMount(){ const go=()=>window.SWD?SWD.ready(()=>this.init()):setTimeout(go,30); go(); }
  init(){
    const D=SW_DEMO_DATA, CF=SW_DEMO, $=id=>document.getElementById(id), UF=SWD.UFS(), CT=CF.country, T=D.ts;
    SWD.page({active:'vida',lv:'BR',label:'Esperança de vida'});
    $('vstamp').innerHTML=SWD.stamp('e0'); $('src').innerHTML=SWD.srcLine(['e0'])+' Os valores vêm das tábuas de mortalidade usadas na projeção.';
    const YS=[2000,2010,2022,2040,2060], st={y:2022,sel:'BR'}, lo=60, hi=90, px=v=>(v-lo)/(hi-lo)*100;
    SWD.seg($('yr'),YS.map(y=>[String(y),String(y)]),'2022',k=>{st.y=+k;draw()},'Ano');
    $('axis').innerHTML=`<span></span><span></span><div>${[60,65,70,75,80,85,90].map(v=>`<span style="left:${px(v)}%">${v}</span>`).join('')}</div><span></span>`;
    const list=$('db');
    list.onclick=e=>{const li=e.target.closest('li[data-uf]'); if(li){st.sel=st.sel===li.dataset.uf?'BR':li.dataset.uf;draw()}};
    list.onkeydown=e=>{ if(!['ArrowDown','ArrowUp'].includes(e.key)) return; e.preventDefault(); const ord=[...list.querySelectorAll('li')].map(l=>l.dataset.uf); let i=ord.indexOf(st.sel); i=Math.max(0,Math.min(ord.length-1,i+(e.key==='ArrowDown'?1:-1))); st.sel=ord[i]; draw(); list.querySelector(`li[data-uf="${st.sel}"]`).focus(); };
    const draw=()=>{ const y=st.y, g=(k,u)=>T[k][u]?T[k][u][y]:null, u=st.sel, br=g('e0','BR');
      $('chg').innerHTML=`<div><small>${SWD.name(u)}, ${y}</small><b>${SWD.num(g('e0',u),1)} anos</b></div><div><small>Homens</small><b>${SWD.num(g('e0m',u),1)}</b></div><div><small>Mulheres</small><b>${SWD.num(g('e0f',u),1)}</b></div><div><small>Diferença</small><b>${SWD.num(g('e0f',u)-g('e0m',u),1)} anos</b></div>`;
      $('brl').textContent=`${CT.name}, ${SWD.num(br,1)} anos`;
      const ord=UF.slice().sort((a,b)=>g('e0',b)-g('e0',a));
      list.innerHTML=ord.map((v,i)=>{const m=g('e0m',v), f=g('e0f',v);
        return `<li data-uf="${v}" role="option" tabindex="${v===st.sel||(st.sel==='BR'&&i===0)?0:-1}" aria-selected="${v===st.sel}" class="${v===st.sel?'on':''}" aria-label="${SWD.name(v)}: homens ${SWD.num(m,1)}, mulheres ${SWD.num(f,1)} anos"><span class="n">${i+1}</span><span class="nm" style="white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${SWD.name(v)}</span>
          <span class="tr"><em style="left:${px(br)}%"></em><s style="left:${px(m)}%;width:${px(f)-px(m)}%"></s><b class="m" style="left:${px(m)}%"></b><b class="f" style="left:${px(f)}%"></b></span>
          <span class="v"><b>${SWD.num(g('e0',v),1)}</b> anos</span></li>`}).join('');
      document.querySelectorAll('#chg div').forEach(d=>d.style.minWidth='0');
    };
    draw();
  }
  renderVals(){ return {}; }
}
